CREATE INDEX "idx_books_catalog" ON "books" USING btree ("language_code","publication_year","num_pages","average_rating","isbn") WHERE "books"."publication_year" >= 1950 AND "books"."publication_year" <= 2023 AND "books"."num_pages" <= 1000 AND "books"."image_url" IS NOT NULL AND "books"."image_url" != 'https://s.gr-assets.com/assets/nophoto/book/111x148-bcc042a9c91a29c1d680899eff700a03.png';